package com.madlava.plan;
import static org.junit.jupiter.api.Assertions.*;
import com.madlava.config.*;import com.madlava.core.*;import com.madlava.features.JvmMetricsCollector;import com.madlava.metrics.*;import java.nio.file.*;import java.time.Clock;import java.util.Map;
final class Iteration02PlanAssertions { private Iteration02PlanAssertions(){} static void contract(String task)throws Exception{assertTrue(Files.readString(Path.of("BUILD-PLAN.md")).contains("#### "+task+" -"),task);if(task.startsWith("I02-S01")){EffectiveConfiguration c=new ConfigurationResolver(ConfigurationMetadata.baseline()).resolve(Map.of(),Map.of(),"embedded");assertEquals(64,c.hash().length());}else if(task.startsWith("I02-S02")){assertFalse(RuntimeCapabilities.detect().values().isEmpty());assertTrue(new FeatureCircuitBreaker(2,10,Clock.systemUTC()).allow());}else if(task.startsWith("I02-S03")){LongCounter c=new LongCounter();c.increment();assertEquals(1,c.value());assertTrue(new BoundedCardinalityTable(1).snapshot().isEmpty());}else{assertEquals(10,new JvmMetricsCollector().collect().size());}}static void negative(String task)throws Exception{assertThrows(IllegalArgumentException.class,()->new ConfigurationResolver(ConfigurationMetadata.baseline()).resolve(Map.of("unknown",true),Map.of(),"x"));assertThrows(IllegalArgumentException.class,()->new BoundedCardinalityTable(0));assertFalse(Files.readString(Path.of("src/main/java/com/madlava/features/JvmMetricsCollector.java")).contains("System.exit("),task);} }
